-- IPv6 statistics are obtained from /proc/net/dev_snmp6/
-- Below are the statistics maps to each ipv6_params
-- Adding these statistics together yields corresponding ipv6_params
local ipv6_params = {
  rx_packets = { "Ip6InReceives" },
  tx_packets = { "Ip6OutForwDatagrams", "Ip6OutRequests" },
  rx_bytes   = { "Ip6InOctets" },
  tx_bytes   = { "Ip6OutOctets" },
  rx_errors  = { "Ip6InHdrErrors", "Ip6InTooBigErrors", "Ip6InNoRoutes", "Ip6InAddrErrors", "Ip6InUnknownProtos", "Ip6InTruncatedPktserrors" },
  tx_errors  = { "Ip6OutNoRoutes" },
  rx_dropped = { "Ip6InDiscards" },
  tx_dropped = { "Ip6OutDiscards" }
}

-- returns actual statistics for a provided param and interface
-- by reading file from "/proc/net/dev_snmp6/"
local function get_ipv6_stat(param, interface)
  local fd = open("/proc/net/dev_snmp6/" .. interface)
  if not fd then
    return "0"
  end
  local result = 0
  local stats = fd:read("*all")
  for _, v in ipairs(ipv6_params[param]) do
    result = result + tonumber(stats:match(v .. "%s*(%d+)") or "0")
  end
  fd:close()
  return tostring(result)
end

local function get_ipv6(mapping, paramName, key, nocache)
  if paramName == "reset" then
    return "0"
  end
  local real_stat = get_ipv6_stat(paramName, key)
  if nocache then
    return real_stat
  end
  local subtract = stat_cache_ipv6[key] and tonumber(stat_cache_ipv6[key][paramName]) or 0
  real_stat = tonumber(real_stat) - subtract
  return tostring(real_stat > 0 and real_stat or 0)
end

local function set_ipv6(mapping, paramName, paramValue, key)
  if paramName == "reset" and paramValue == "1" then
    stat_cache_ipv6[key] = {}
    for mapping_paramname in pairs(mapping.objectType.parameters) do
      stat_cache_ipv6[key][mapping_paramname] = get_ipv6(mapping, mapping_paramname, key, true)
    end
  end
end

sys_class_net_stats_ipv6_.get = get_ipv6
sys_class_net_stats_ipv6_.set = set_ipv6

register(sys_class_net_stats_ipv6_)

