-- IPv4 statistics are obtained from subtracting IPv6 statistics from total statistics
local function get_ipv4(mapping, paramName, key, nocache)
  if paramName == "reset" then
    return "0"
  end
  local real_stat = firstline("/sys/class/net/" .. key .. "/statistics/" .. paramName) - tonumber(get_ipv6_stat(paramName, key))
  if nocache then
    return tostring(real_stat)
  end
  local subtract = stat_cache_ipv4[key] and tonumber(stat_cache_ipv4[key][paramName]) or 0
  real_stat = real_stat - subtract
  return tostring(real_stat > 0 and real_stat or 0)
end

local function set_ipv4(mapping, paramName, paramValue, key)
  if paramName == "reset" and paramValue == "1" then
    stat_cache_ipv4[key] = {}
    for mapping_paramname in pairs(mapping.objectType.parameters) do
      stat_cache_ipv4[key][mapping_paramname] = get_ipv4(mapping, mapping_paramname, key, true)
    end
  end
end

sys_class_net_stats_ipv4_.get = get_ipv4
sys_class_net_stats_ipv4_.set = set_ipv4

register(sys_class_net_stats_ipv4_)